"""Generate targeted candidate stimulus pairs for the design agent.

Targets disagreement among the four models:
  - artificial_balance           (reads n, h, rep_motifs, alt_motifs; penalizes
                                   contrived h~=n/2 balance and motif structure)
  - minkowski_accumulated_type.  (reads n, h, alts -> p and alt_rate; loves
                                   p~=0.5, moderate alternation, long lengths)
  - evidence_accumulation_per_run(read alts, imbalance, p_alts; accumulates over
                                   runs = alts+1; penalizes run-poor patterns)
  - evidence_accumulation_messy  (reads n, imbalance, p_alts; accumulates over n)

Families:
  BALANCE        balanced vs imbalanced at matched length+alternation.
                   (balance-preferrers disagree with artificial_balance)
  ALTERNATION    high- vs low-alternation at matched length (+/- balance).
                   (per_run vs messy/minkowski; asymmetric alt penalty)
  RUNSTRUCT      same n, h, alts but different run/motif layout.
                   (isolates artificial_balance's motif features)
  LENGTH         near-ideal long vs short; deviant long vs short.
                   (minkowski/messy scale n; clarify per-item vs per-run)
  PERIODIC       exact periodic patterns (high runs, artificial) vs messy.
  BROAD          random diverse pairs as a coverage fallback.
"""
import itertools
import json
import random
from pathlib import Path

random.seed(42)

OUT = Path(
    "/Users/ben/Documents/auto-psych/data/subjective_randomness/holdout_recovery_deepseek"
    "/holdout_runs/local_representativeness/experiment1/design/candidates.json"
)

def runcount(s: str) -> int:
    return sum(1 for i in range(1, len(s)) if s[i] != s[i - 1]) + 1

def alt_count(s: str) -> int:
    return sum(1 for i in range(1, len(s)) if s[i] != s[i - 1])

def h_count(s: str) -> int:
    return s.count("H")

def imbalance(s: str) -> int:
    return abs(2 * h_count(s) - len(s))

# ---------- curated signature sequences, grouped by family ----------
seqs = {
    "per_balanced": [],   # exact equal H/T, high alternation (artificial/periodic)
    "messy": [],          # near-ideal balance + moderate alternation
    "run_heavy": [],      # long runs (few transitions)
    "imbalanced": [],     # clear H/T imbalance
    "periodic": [],       # repeating short templates
}

def add(family, s):
    if 2 <= len(s) <= 8 and s not in seqs[family]:
        seqs[family].append(s)

# PERIODIC + artificial-balanced alternators (penalized hard by artificial_balance)
for n in range(4, 9):
    for t in ["HT", "TH", "HH", "TT", "HHTT", "HTHH"]:
        t = t * n
        add("periodic", t[:n])
    # exact rollovers
    p = "HTHTHT"
    add("periodic", p[:n])

# MESSY: balanced-ish, moderate alternation, no long runs, no exact balance
for n in range(4, 9):
    half = n // 2
    # some H ~ n/2 +/- 1, alternation around 0.5-0.7
    for h in range(max(0, half - 1), min(n, half + 2) + 1):
        for _ in range(6):
            s = list("H" * h + "T" * (n - h))
            random.shuffle(s)
            s = "".join(s)
            a = alt_count(s)
            if 0.4 <= a / (n - 1) <= 0.75:
                add("messy", s)

# RUN-HEAVY: few transitions, long runs, balanced and imbalanced
for n in range(3, 9):
    adds = ["H" * n, "T" * n,
            "H" * (n - 1) + "T", "H" + "T" * (n - 1),
            "H" * max(1, n // 2) + "T" * (n - n // 2),
            "T" * max(1, n // 2) + "H" * (n - n // 2),
            "H" * (n // 2) + "T" * (n - n // 2)]
    for s in adds:
        add("run_heavy", s)
# two-long-run balanced patterns like HHTT, HHHHTTTT
add("run_heavy", "HHTT"); add("run_heavy", "HHTHTT")

# IMBALANCED: clear imbalance, moderate alternation
for n in range(3, 9):
    for h in range(0, n + 1):
        if abs(2 * h - n) >= 2:
            for _ in range(4):
                s = "".join(random.sample("H" * h + "T" * (n - h), n))
                if 0.2 <= alt_count(s) / (n - 1) <= 0.8:
                    add("imbalanced", s)

base = {
    **seqs,
    "balanced_exact": ["HHTT", "HTHH", "THHT", "HHTHTT", "HTHHTT",
                       "HTHTHH", "THHTTH", "HHTTHT", "HHTHTH", "TTHTHT"],
}
# de-dup across families
seen = {}
all_seqs = []
for fam, lst in base.items():
    for s in lst:
        s = s.strip()
        if s not in seen and 2 <= len(s) <= 8:
            seen[s] = 0
            all_seqs.append(s)

# ---------- build pairs ----------
pairs = []
def add_pair(a, b):
    if a == b:
        return
    if random.random() < 0.5:
        a, b = b, a
    pairs.append({"sequence_a": a, "sequence_b": b})

# BALANCE family: balanced vs imbalanced, matched length & alternation
for n in range(4, 9):
    mid_runs = []
    for s in all_seqs:
        if len(s) == n and abs(2 * h_count(s) - n) == 0:
            a = alt_count(s)
            if 0.4 <= a / (n - 1) <= 0.7:
                mid_runs.append(s)
    # find an imbalanced counterpart with same alternation
    for bal in mid_runs:
        a = alt_count(bal)
        cands = [s for s in all_seqs
                 if len(s) == n and abs(2 * h_count(s) - n) >= 2 and alt_count(s) == a]
        if cands:
            add_pair(bal, random.choice(cands))

# ALTERNATION family: high- vs low-alternation at matched length & balance
for n in range(4, 9):
    half = n // 2
    hi = [s for s in all_seqs if len(s) == n and abs(2 * h_count(s) - n) == 0
          and alt_count(s) >= n - 2]
    lo = [s for s in all_seqs if len(s) == n and abs(2 * h_count(s) - n) == 0
          and alt_count(s) <= (n - 1) // 2]
    if hi and lo:
        add_pair(random.choice(hi), random.choice(lo))

# RUNSTRUCT family: same n, h, alts, different motif/run layout (isolate artificial_balance)
by_sig = {}
for s in all_seqs:
    by_sig.setdefault((len(s), h_count(s), alt_count(s)), []).append(s)
for sig, grp in by_sig.items():
    for a, b in itertools.combinations(grp, 2):
        if a != b:
            add_pair(a, b)

# LENGTH family: near-ideal long vs short; deviant long vs short
ideal_long = [s for s in all_seqs if len(s) >= 6 and abs(2 * h_count(s) - len(s)) <= 1
              and 0.4 <= alt_count(s) / (len(s) - 1) <= 0.7]
ideal_short = [s for s in all_seqs if 2 <= len(s) <= 4 and abs(2 * h_count(s) - len(s)) <= 1]
if ideal_long and ideal_short:
    for _ in range(40):
        add_pair(random.choice(ideal_long), random.choice(ideal_short))

# PERIODIC vs messy (no exact balance differ, high alternation artificial)
for n in range(4, 9):
    per = [s for s in seqs["periodic"] if len(s) == n]
    mes = [s for s in all_seqs if len(s) == n and abs(2 * h_count(s) - n) == 0
           and 0.4 <= alt_count(s) / (n - 1) <= 0.7]
    if per and mes:
        for p in random.sample(per, min(3, len(per))):
            add_pair(p, random.choice(mes))

# All-pairs among a diverse subset (strong coverage, incl. cross-length)
diverse = random.sample(all_seqs, min(120, len(all_seqs)))
for a, b in itertools.combinations(diverse, 2):
    if len(a) != len(b):  # cross-length pool
        add_pair(a, b)

# BROAD random same-length + cross-length pairs (coverage fallback)
for _ in range(1500):
    a = random.choice(all_seqs)
    b = random.choice(all_seqs)
    add_pair(a, b)
    # also generate fresh random strings for broader space coverage
    na = random.randint(2, 8)
    nb = random.randint(2, 8)
    sa = "".join(random.choice("HT") for _ in range(na))
    sb = "".join(random.choice("HT") for _ in range(nb))
    add_pair(sa, sb)

seen_pairs = {}
final = []
for p in pairs:
    key = tuple(sorted((p["sequence_a"], p["sequence_b"])))
    if key in seen_pairs:
        continue
    seen_pairs[key] = 1
    final.append(p)

OUT.parent.mkdir(parents=True, exist_ok=True)
OUT.write_text(json.dumps(final, indent=2), encoding="utf-8")
print(f"wrote {len(final)} unique candidate pairs to {OUT}")
